// Final Musicbox: the purple object, slot 5 (its NFC tag opens …/?pick=5)
// Everything here belongs to this one object. Save the file and reload the page to see a change.
// The look shared by every object (the ash, the burn, the timing, the dots) is in index.html.
// Preview this object straight away: open index.html?play=5  (add &layer=2 or &layer=3 to jump to that layer)
//
//   name:   just a label
//   colour: its dot on the last layer (and its flakes on the second layer, unless flake is set)
//   words:  the three words left in ash on the second layer
//   image:  its silhouette (null = not made yet: it is skipped, but its dot still shows). Send Claude a new picture to prepare it.
//
// Optional fine-tuning (leave a line out to use the shared setting from index.html):
//   size:   how big it is on screen (1 = as big as fits, lower = smaller)
//   flat:   how evenly shaded its flakes are on the first layer (0 = full shading and detail, 1 = one flat shade)
//   mist:   how soft and dispersed its outline is on the first layer (0 = crisp, 1 = very hazy)
//   spread: how far its silhouette scatters on the second layer (1 = the usual; a wide, solid object reads better lower)
//   fade2:  how solid its flakes stay on the second layer (lower = softer and more see-through)
//   edge:   how hard the flakes around its outline burst outward after the first swipe (0 = none)
//   flake:  the colour of its flakes on the second layer
//   flakeSize: how big its flakes are compared with the other objects' (1 = the same, lower = smaller)
//   density: how many flakes make it up (1 = the usual, higher = finer detail, a little more work for the phone)
//   notes:  a paragraph for each word: the word becomes a button on the second layer that opens it (leave out for plain words)
//   title:  the small heading shown above the word in that pop-up

OBJECT(5, {
  name: "musicbox",
  colour: "#754992",
  words: ["Gift", "Copies", "Betrayal"],
  title: "Music Box",
  notes: {
    Gift: "A purple music box was chosen with care, a gift that seemed to say, \u201cI\u2019ve been paying attention.\u201d",
    Copies: "But each time it played, another box appeared with a different name engraved. Soon there were many, all identical, all playing the same sweet song.",
    Betrayal: "Theirs was a story of cheating, where something that felt one of a kind had been given to many.",
  },

  size: .6,
  flat: 0,    // keeps its shading, so its details show
  density: 7,  // more, finer flakes for a sharper picture (1 = the usual)
  flakeSize: .5, // its flakes are smaller than the other objects' (1 = the same size)
  mist: .3,      // a lightly softened outline (the crank and edges still read)
  spread: .3,
  flake: "#6d5180",

  image: "data:image/webp;base64,"
});
